mapper.select:
SELECT

FROM t_dict


        AND (
        INSTR(t_dict.dict_name,#{keywords})
        OR INSTR(t_dict.dict_code,#{keywords})
        OR INSTR(t_dict.remark,#{keywords})
        )


        AND t_dict.disabled_flag = #{disabledFlag}


ORDER BY create_time DESC

    LIMIT #{offset}, #{limit}
